def parse_csv_line(line: str) -> list[str]:
    fields = []
    current_field = []
    in_quotes = False
    i = 0
    while i < len(line):
        char = line[i]
        if char == '"':
            if not in_quotes:
                in_quotes = True
            else:
                if i + 1 < len(line) and line[i+1] == '"':
                    current_field.append('"')
                    i += 1
                else:
                    in_quotes = False
        elif char == ',' and not in_quotes:
            fields.append("".join(current_field))
            current_field = []
        else:
            current_field.append(char)
        i += 1
    fields.append("".join(current_field))
    return fields
```

