def luhn_valid(number: str) -> bool:
    digits = [int(d) for d in number if d != ' ']
    checksum = 0
    for i, digit in enumerate(reversed(digits)):
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        checksum += digit
    return checksum % 10 == 0
```

