from itertools import zip_longest

def semver_cmp(a: str, b: str) -> int:
    parts_a = map(int, a.split('.'))
    parts_b = map(int, b.split('.'))
    for va, vb in zip_longest(parts_a, parts_b, fillvalue=0):
        if va < vb:
            return -1
        if va > vb:
            return 1
    return 0
```

